// craftsman-ignore: TS001,TS002
import React, { useEffect, useState } from 'react';
import { Row, Col, Button, Typography, Switch, Slider, Tag } from 'antd';
import { message } from '../utils/feedback';
import { companionsApi } from '../api/companions';
import {
  orderTypeConfig,
  serviceTypeConfig,
  dispatchTypeConfig,
  urgencyConfig,
  billingModeConfig,
} from '../constants';
import { ORDER_FIELD_LABELS } from '../constants/orderFields';
import BannerFullscreenModeSetting from './BannerFullscreenModeSetting';

/**
 * 陪玩端「订单通知设置」面板（2026-10-08 老板报王甲振那台之后抽出来的）。
 *
 * 老板原话：「刚才看了王甲振电脑，他设置里没有关弹窗的地方，并且没弹窗」。
 * 两件事其实是两个原因：
 *   ① **找不到地方**：这些开关以前只挂在「陪玩首页卡片右上角那颗 🔔 图标」里，
 *      左侧菜单「设置」下只有「个人设置」，所以从菜单进去永远找不到 —— 现在这一份内容
 *      既在首页 🔔 弹窗里，也挂在「设置 → 通知设置」页（同一个组件，改一处两边都变）；
 *   ② **为什么不弹**：王甲振当时是「接单中」，而且本人的「打单中也接收新单弹窗」是关的 ——
 *      这是系统定的规则（空闲 / 挂机一律弹；接单中 / 娱乐中自己开关，接单中默认不弹），不是坏了。
 *      所以面板顶部直接把「你现在是什么状态 → 现在到底弹不弹、为什么」写在脸上。
 *
 * 规则跟服务端 ws.gateway.ts 的 urgentRecipientWhere **必须一致**：
 *   空闲 / 挂机（休息）一律弹；娱乐中看 notifyWhileEntertainment（默认开）；接单中看 notifyWhileBusy（默认关）。
 */

/** 通知过滤设置里的开关标签，一律取 constants/orders.ts 的唯一一份（跟发布订单表单同一套字）。 */
const configItems = (cfg: Record<string, { label: string; color: string }>) =>
  Object.entries(cfg).map(([k, c]) => ({ k, l: c.label, c: c.color }));

export interface NotifyDecision {
  /** 现在这个状态下，新单会不会弹给他 */
  pop: boolean;
  /** 一句话说清为什么（给陪玩看的中文） */
  why: string;
}

/**
 * 「他现在这个状态，新单到底弹不弹」——纯函数，方便单测。
 * 口径严格抄服务端 urgentRecipientWhere，别在这里另立一套。
 */
export function notifyDecision(
  status: string | null | undefined,
  prefs: { notifyWhileBusy: boolean; notifyWhileEntertainment: boolean },
): NotifyDecision {
  switch (status) {
    case 'AVAILABLE':
      return { pop: true, why: '空闲中 —— 新单一律弹，不受下面两个开关影响' };
    case 'RESTING':
      return { pop: true, why: '挂机（休息）中 —— 新单一律弹，不受下面两个开关影响' };
    case 'BUSY':
      return prefs.notifyWhileBusy
        ? { pop: true, why: '接单中 —— 你打开了「打单中也接收新单弹窗」，会弹' }
        : {
            pop: false,
            why: '接单中 —— 「打单中也接收新单弹窗」关着，所以现在不弹新单；想打单时也接到单，打开上面那个开关',
          };
    case 'ENTERTAINMENT':
      return prefs.notifyWhileEntertainment
        ? { pop: true, why: '娱乐中 —— 你打开了「娱乐中也接收新单弹窗」，会弹' }
        : { pop: false, why: '娱乐中 —— 「娱乐中也接收新单弹窗」关着，所以现在不弹新单' };
    default:
      return { pop: false, why: '现在不在线（离线 / 状态未知）—— 上线后按上面的规则弹' };
  }
}

export default function OrderNotifySettingsPanel() {
  const [notifyWhileBusy, setNotifyWhileBusy] = useState(false);
  // 老板 2026-10-01：接单中 / 娱乐中才能自己关弹窗；空闲 / 挂机（休息）一律弹，不受这里影响。
  const [notifyWhileEntertainment, setNotifyWhileEntertainment] = useState(true);
  const [notifyStatus, setNotifyStatus] = useState<string | null>(null);
  const [notifSound, setNotifSound] = useState(true);
  const [notifVolume, setNotifVolume] = useState(70);
  const [notifPrefs, setNotifPrefs] = useState<any>({
    enabled: true,
    orderTypes: { NEW: true, RENEW: true, REPURCHASE: true, TIP: true },
    serviceTypes: { PLAY_WITH: true, ESCORT: true, DO_TASK: true },
    dispatchTypes: { POOL: true, DIRECT: true },
    urgency: { now: true, later: true },
    billingMode: { hour: true, round: true },
    deltaCount: { 单: true, 双: true },
    deltaMission: { 机密: true, 绝密: true },
    customerSource: { 小红书: true, 抖音: true, 快手: true, 转介绍: true },
  });

  useEffect(() => {
    companionsApi
      .notifyPrefs()
      .then(({ data }: any) => {
        setNotifyWhileBusy(!!data?.data?.notifyWhileBusy);
        setNotifyWhileEntertainment(data?.data?.notifyWhileEntertainment !== false);
        setNotifyStatus(data?.data?.status ?? null);
      })
      .catch(() => {});
  }, []);

  const saveNotifPrefs = async (prefs: any) => {
    setNotifPrefs(prefs);
    try {
      await (window as any).electronAPI?.storeSet('notificationPrefs', prefs);
    } catch {}
  };

  const decision = notifyDecision(notifyStatus, { notifyWhileBusy, notifyWhileEntertainment });

  return (
    <>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 14, flexWrap: 'wrap' }}>
        <Tag color={decision.pop ? 'green' : 'orange'} style={{ margin: 0 }}>
          {decision.pop ? '现在会弹新单' : '现在不弹新单'}
        </Tag>
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          {decision.why}
        </Typography.Text>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', marginBottom: 14 }}>
        <Typography.Text strong style={{ marginRight: 12 }}>
          启用通知
        </Typography.Text>
        <Switch
          checked={notifPrefs?.enabled !== false}
          onChange={(v) => saveNotifPrefs({ ...notifPrefs, enabled: v })}
        />
      </div>
      <div style={{ display: 'flex', alignItems: 'center', marginBottom: 6, gap: 12 }}>
        <Typography.Text strong>打单中也接收新单弹窗</Typography.Text>
        <Switch
          checked={notifyWhileBusy}
          onChange={async (v) => {
            setNotifyWhileBusy(v);
            try {
              await companionsApi.setNotifyPrefs({ notifyWhileBusy: v });
              message.success(v ? '已打开：正在打单时也会弹新单' : '已关闭：打单时不打扰');
            } catch {
              setNotifyWhileBusy(!v);
              message.error('保存失败，请重试');
            }
          }}
        />
      </div>
      <Typography.Text type="secondary" style={{ fontSize: 12, display: 'block', marginBottom: 14 }}>
        空闲、挂机（休息）一定会弹，不受下面两个开关影响；下面两个开关只管「正在打单」和
        「娱乐中」的时候 —— 想图清净就关上，想多抢单就打开。
      </Typography.Text>
      <div style={{ display: 'flex', alignItems: 'center', marginBottom: 6, gap: 12 }}>
        <Typography.Text strong>娱乐中也接收新单弹窗</Typography.Text>
        <Switch
          checked={notifyWhileEntertainment}
          onChange={async (v) => {
            setNotifyWhileEntertainment(v);
            try {
              await companionsApi.setNotifyPrefs({ notifyWhileEntertainment: v });
              message.success(v ? '已打开：娱乐中也会弹新单' : '已关闭：娱乐中不打扰');
            } catch {
              setNotifyWhileEntertainment(!v);
              message.error('保存失败，请重试');
            }
          }}
        />
      </div>
      <Typography.Text type="secondary" style={{ fontSize: 12, display: 'block', marginBottom: 14 }}>
        娱乐中也能抢单（弹窗里带订单号，点一下跳到抢单池）；不想被打扰就关上。
      </Typography.Text>
      <BannerFullscreenModeSetting />
      <div style={{ display: 'flex', alignItems: 'center', marginBottom: 14, gap: 16 }}>
        <Typography.Text strong>提示音</Typography.Text>
        <Switch
          checked={notifSound}
          onChange={async (v) => {
            setNotifSound(v);
            try {
              await (window as any).electronAPI?.storeSet('notifSound', v);
            } catch {}
          }}
        />
        <Typography.Text>音量</Typography.Text>
        <Slider
          style={{ width: 120 }}
          min={0}
          max={100}
          value={notifVolume}
          onChange={async (v) => {
            setNotifVolume(v);
            try {
              await (window as any).electronAPI?.storeSet('notifVolume', v);
            } catch {}
          }}
        />
        <Button
          size="small"
          onClick={() => {
            try {
              const a = new Audio(
                'data:audio/wav;base64,',
              );
              a.volume = notifVolume / 100;
              a.play();
            } catch {}
          }}
        >
          🔊
        </Button>
      </div>
      <Row gutter={[8, 14]}>
        {[
          { key: 'orderTypes', title: ORDER_FIELD_LABELS.orderType, items: configItems(orderTypeConfig) },
          { key: 'serviceTypes', title: ORDER_FIELD_LABELS.serviceType, items: configItems(serviceTypeConfig) },
          {
            // 派单方式：广播这一项老版本没有开关，行为保持不变，先不列出来
            key: 'dispatchTypes',
            title: '派单方式',
            items: configItems(dispatchTypeConfig).filter((i) => i.k !== 'BROADCAST'),
          },
          { key: 'urgency', title: ORDER_FIELD_LABELS.urgency, items: configItems(urgencyConfig) },
          { key: 'billingMode', title: ORDER_FIELD_LABELS.billingMode, items: configItems(billingModeConfig) },
          {
            key: 'deltaCount',
            title: ORDER_FIELD_LABELS.deltaCount,
            items: [
              { k: '单', l: '单陪', c: 'blue' },
              { k: '双', l: '双陪', c: 'purple' },
            ],
          },
          {
            key: 'deltaMission',
            title: ORDER_FIELD_LABELS.deltaMission,
            items: [
              { k: '机密', l: '机密', c: 'orange' },
              { k: '绝密', l: '绝密', c: 'purple' },
            ],
          },
          {
            key: 'customerSource',
            title: ORDER_FIELD_LABELS.customerSource,
            items: [
              { k: '小红书', l: '小红书', c: 'red' },
              { k: '抖音', l: '抖音', c: 'blue' },
              { k: '快手', l: '快手', c: 'orange' },
              { k: '转介绍', l: '转介绍', c: 'green' },
            ],
          },
        ].map((sec: any) => (
          <Col span={8} key={sec.key}>
            <Typography.Text type="secondary" style={{ display: 'block', marginBottom: 4 }}>
              {sec.title}
            </Typography.Text>
            {sec.items.map(({ k, l, c }: any) => (
              <div key={k} style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 3 }}>
                <Tag color={c} style={{ margin: 0, fontSize: 11 }}>
                  {l}
                </Tag>
                <Switch
                  size="small"
                  checked={notifPrefs?.[sec.key]?.[k] !== false}
                  disabled={!notifPrefs?.enabled}
                  onChange={(v) => saveNotifPrefs({ ...notifPrefs, [sec.key]: { ...notifPrefs?.[sec.key], [k]: v } })}
                />
              </div>
            ))}
          </Col>
        ))}
      </Row>
    </>
  );
}
